mapper.select:
SELECT L.API_CALL_LOG_ID, L.EXTERNAL_API_ID, A.API_NAME, L.FIRE_INSTANCE_ID, L.ATTEMPT_NO, L.HTTP_STATUS, L.STARTED_AT, L.FINISHED_AT, L.RUN_MILLIS, L.STATUS, L.ERROR_MESSAGE, L.CREATED_AT FROM SCHED_EXTERNAL_API_CALL_LOG L LEFT JOIN SCHED_EXTERNAL_API A ON L.EXTERNAL_API_ID = A.EXTERNAL_API_ID WHERE 1 = 1
AND A.API_NAME LIKE '%' || #{apiName} || '%'
AND L.STATUS = #{status}
AND L.STARTED_AT >= #{startDate}
AND L.STARTED_AT < #{endDateExclusive}
ORDER BY L.CREATED_AT DESC, L.API_CALL_LOG_ID DESC OFFSET #{offset} ROWS FETCH NEXT #{size} ROWS ONLY

SELECT COUNT(*)
FROM SCHED_EXTERNAL_API_CALL_LOG L
LEFT JOIN SCHED_EXTERNAL_API A
  ON L.EXTERNAL_API_ID = A.EXTERNAL_API_ID
WHERE 1 = 1

	AND A.API_NAME LIKE '%' || #{apiName} || '%'


	AND L.STATUS = #{status}


	AND L.STARTED_AT  >=  #{startDate}


	AND L.STARTED_AT  <  #{endDateExclusive}

SELECT S.EXECUTION_ID, S.EXTERNAL_API_ID, S.API_NAME, S.FIRE_INSTANCE_ID, L.STATUS, S.ATTEMPT_COUNT, S.ATTEMPT_COUNT - 1 AS RETRY_COUNT, S.API_RUN_MILLIS, S.STARTED_AT, S.FINISHED_AT FROM ( SELECT L.EXECUTION_ID, L.EXTERNAL_API_ID, A.API_NAME, MAX(L.FIRE_INSTANCE_ID) AS FIRE_INSTANCE_ID, COUNT(*) AS ATTEMPT_COUNT, COALESCE(SUM(L.RUN_MILLIS), 0) AS API_RUN_MILLIS, MIN(L.STARTED_AT) AS STARTED_AT, MAX(L.FINISHED_AT) AS FINISHED_AT, MAX(L.ATTEMPT_NO) AS LAST_ATTEMPT_NO FROM SCHED_EXTERNAL_API_CALL_LOG L LEFT JOIN SCHED_EXTERNAL_API A ON L.EXTERNAL_API_ID = A.EXTERNAL_API_ID WHERE L.EXECUTION_ID IS NOT NULL
AND A.API_NAME LIKE '%' || #{apiName} || '%'
AND L.STARTED_AT >= #{startDate}
AND L.STARTED_AT < #{endDateExclusive}
GROUP BY L.EXECUTION_ID, L.EXTERNAL_API_ID, A.API_NAME ) S JOIN SCHED_EXTERNAL_API_CALL_LOG L ON L.EXECUTION_ID = S.EXECUTION_ID AND L.ATTEMPT_NO = S.LAST_ATTEMPT_NO
L.STATUS = #{status}
ORDER BY S.STARTED_AT DESC OFFSET #{offset} ROWS FETCH NEXT #{size} ROWS ONLY

SELECT COUNT(*) FROM ( SELECT L.EXECUTION_ID, MAX(L.ATTEMPT_NO) AS LAST_ATTEMPT_NO FROM SCHED_EXTERNAL_API_CALL_LOG L LEFT JOIN SCHED_EXTERNAL_API A ON L.EXTERNAL_API_ID = A.EXTERNAL_API_ID WHERE L.EXECUTION_ID IS NOT NULL
AND A.API_NAME LIKE '%' || #{apiName} || '%'
AND L.STARTED_AT >= #{startDate}
AND L.STARTED_AT < #{endDateExclusive}
GROUP BY L.EXECUTION_ID ) S JOIN SCHED_EXTERNAL_API_CALL_LOG L ON L.EXECUTION_ID = S.EXECUTION_ID AND L.ATTEMPT_NO = S.LAST_ATTEMPT_NO
L.STATUS = #{status}
